#define Pi 3.1415926535
#define Pi2 (Pi*2.)
#define time (iTime/6.)
#define resolution iResolution

mat2 rot(float angle) {
return mat2(cos(angle),-sin(angle),sin(angle),cos(angle));
}

float rand(float t) {
return sin(t*29.524)*3.5255;
}

float smoothnoise(float x) {
x = x/3.*2.;
float t = time *2.;
float f = sin(x*2.+t);
float f2 = sin(x*4.-t);
float f3 = sin(x*12.+t*4.)*.3;
float f4 = sin(x*130.-t)*.2;
float res = (f+f2+f3+f4)/4.;
return res;
}

vec3 palette( float p ) {
vec3 a = vec3(0.5, 0.5, 0.5);
vec3 b = vec3(0.5, 0.5, 0.5);
vec3 c1 = vec3(1.0, 1.0, 1.0);
vec3 c2 = vec3(.8,.8,.5);
vec3 d1 = vec3(0., 0.33, 0.67);
vec3 d2 = vec3(.0, .2, .5);
vec3 c = mix(c2,c1, sin(time*2.)*.5+.5 );
vec3 d = mix(d2,d1, sin(time)*.5+.5 );

return a + b*cos( Pi2*(c*p+d) );
}

vec3 palette2( float p ) {
vec3 a = vec3(0.5, 0.5, 0.5);
vec3 b = vec3(0.5, 0.5, 0.5);
vec3 c = vec3(.8, .8, .5);
vec3 d = vec3(0., 0.3, 0.6);

return a + b*cos( Pi2*(c*p+d) );
}


void mainImage( out vec4 fragColor, in vec2 fragCoord ){
vec2 uv = (fragCoord.xy / resolution.xy) *2. -1.;
uv.y *= resolution.y/resolution.x;
uv/=2.;
uv *= rot(time/2.*3.1415);
uv = vec2(atan(uv.x,uv.y),length(uv));
vec3 col = vec3(0);
//col += vec3(uv,1.);
uv.y = 1.-pow(abs(uv.y-1.),8.);


float cir = cos((abs((uv.y-time)*5.)) + sin(smoothnoise(uv.x*5.)))+15.;
col = palette(cir);
col *= palette(0.);
float lines = (sin((uv.x-uv.y+time)*6.)/6.);
col /= palette2(lines*.8);
//col += d;
//col=palette(col.z);
fragColor = vec4(col, 1.0);
}
